// SPDX-License-Identifier: GPL-3.0-or-later
//! Runs the value vectors of `docs/especificacao/vetores-de-teste/`
//! (`identidade/`, `envelope/`, `mensagens/`) against the crate.
//!
//! The vectors are generated by `rust/tools/vectors` and committed; this is
//! the executor that proves the crate agrees with them: exact decode and
//! encode of the valid ones, refusal of the invalid ones, `reencode_hex` for
//! the unknown-key case and the identity functions. The test has its own
//! small JSON reader so the crate gains no dev-dependency.

use std::fs;
use std::path::{Path, PathBuf};

use porecatu_protocol::cbor::{self, Value};
use porecatu_protocol::encoding::decode_hex;
use porecatu_protocol::envelope::{
    ChannelId, ClientEnvelope, EnvelopeError, HandshakeStart, HostEnvelope, decode_client,
    decode_handshake_start, decode_host, encode_client, encode_handshake_start, encode_host,
};
use porecatu_protocol::fingerprint::fingerprint;
use porecatu_protocol::host_id::{HostId, host_id};
use porecatu_protocol::pairing_uri::PairingUri;

// ---------------------------------------------------------------------------
// A minimal JSON reader (integers only, as the vectors need)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(entries) => entries.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    fn field(&self, key: &str) -> &Json {
        self.get(key)
            .unwrap_or_else(|| panic!("missing field {key:?}"))
    }

    fn str(&self) -> &str {
        match self {
            Json::Str(s) => s,
            other => panic!("not a string: {other:?}"),
        }
    }

    fn is_null(&self) -> bool {
        matches!(self, Json::Null)
    }

    fn truthy(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            other => panic!("not a boolean: {other:?}"),
        }
    }
}

struct Parser<'a> {
    text: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn parse(text: &'a str) -> Json {
        let mut parser = Parser {
            text: text.as_bytes(),
            pos: 0,
        };
        let value = parser.value();
        parser.skip_space();
        assert_eq!(parser.pos, parser.text.len(), "trailing characters");
        value
    }

    fn skip_space(&mut self) {
        while self.pos < self.text.len() && self.text[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        *self.text.get(self.pos).expect("unexpected end of JSON")
    }

    fn eat(&mut self, byte: u8) {
        assert_eq!(
            self.peek(),
            byte,
            "expected {:?} at {}",
            byte as char,
            self.pos
        );
        self.pos += 1;
    }

    fn literal(&mut self, word: &str, value: Json) -> Json {
        assert!(
            self.text[self.pos..].starts_with(word.as_bytes()),
            "bad literal at {}",
            self.pos
        );
        self.pos += word.len();
        value
    }

    fn value(&mut self) -> Json {
        self.skip_space();
        match self.peek() {
            b'n' => self.literal("null", Json::Null),
            b't' => self.literal("true", Json::Bool(true)),
            b'f' => self.literal("false", Json::Bool(false)),
            b'"' => Json::Str(self.string()),
            b'[' => {
                self.pos += 1;
                let mut items = Vec::new();
                self.skip_space();
                if self.peek() == b']' {
                    self.pos += 1;
                    return Json::Arr(items);
                }
                loop {
                    items.push(self.value());
                    self.skip_space();
                    match self.peek() {
                        b',' => self.pos += 1,
                        b']' => {
                            self.pos += 1;
                            return Json::Arr(items);
                        }
                        other => panic!("unexpected {:?} in an array", other as char),
                    }
                }
            }
            b'{' => {
                self.pos += 1;
                let mut entries = Vec::new();
                self.skip_space();
                if self.peek() == b'}' {
                    self.pos += 1;
                    return Json::Obj(entries);
                }
                loop {
                    self.skip_space();
                    let key = self.string();
                    self.skip_space();
                    self.eat(b':');
                    entries.push((key, self.value()));
                    self.skip_space();
                    match self.peek() {
                        b',' => self.pos += 1,
                        b'}' => {
                            self.pos += 1;
                            return Json::Obj(entries);
                        }
                        other => panic!("unexpected {:?} in an object", other as char),
                    }
                }
            }
            b'-' | b'0'..=b'9' => {
                let start = self.pos;
                self.pos += 1;
                while self.pos < self.text.len() && self.text[self.pos].is_ascii_digit() {
                    self.pos += 1;
                }
                let digits = std::str::from_utf8(&self.text[start..self.pos]).expect("ascii");
                Json::Int(digits.parse().expect("an integer"))
            }
            other => panic!("unexpected {:?} at {}", other as char, self.pos),
        }
    }

    fn hex4(&mut self) -> u32 {
        let digits = std::str::from_utf8(&self.text[self.pos..self.pos + 4]).expect("ascii");
        self.pos += 4;
        u32::from_str_radix(digits, 16).expect("hex digits")
    }

    fn string(&mut self) -> String {
        self.eat(b'"');
        let mut out: Vec<u8> = Vec::new();
        loop {
            let byte = self.peek();
            self.pos += 1;
            match byte {
                b'"' => return String::from_utf8(out).expect("valid UTF-8"),
                b'\\' => {
                    let escape = self.peek();
                    self.pos += 1;
                    let ch = match escape {
                        b'"' => '"',
                        b'\\' => '\\',
                        b'/' => '/',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        b'n' => '\n',
                        b'r' => '\r',
                        b't' => '\t',
                        b'u' => {
                            let mut unit = self.hex4();
                            if (0xd800..0xdc00).contains(&unit) {
                                self.eat(b'\\');
                                self.eat(b'u');
                                let low = self.hex4();
                                unit = 0x10000 + ((unit - 0xd800) << 10) + (low - 0xdc00);
                            }
                            char::from_u32(unit).expect("a scalar value")
                        }
                        other => panic!("bad escape {:?}", other as char),
                    };
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
                other => out.push(other),
            }
        }
    }
}

/// The typed JSON of the README converted to a CBOR value.
fn typed(json: &Json) -> Value {
    match json {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Int(i) => Value::int(*i).expect("an integer within the CBOR domain"),
        Json::Str(s) => Value::Text(s.clone()),
        Json::Arr(items) => Value::Array(items.iter().map(typed).collect()),
        Json::Obj(entries) => match entries.as_slice() {
            [(key, Json::Str(hex))] if key == "bstr" => {
                Value::Bytes(decode_hex(hex).expect("lowercase hex"))
            }
            [(key, Json::Arr(pairs))] if key == "map" => Value::Map(
                pairs
                    .iter()
                    .map(|pair| match pair {
                        Json::Arr(kv) => match kv.as_slice() {
                            [Json::Str(k), v] => (k.clone(), typed(v)),
                            other => panic!("bad map pair {other:?}"),
                        },
                        other => panic!("bad map pair {other:?}"),
                    })
                    .collect(),
            ),
            other => panic!("not a typed object: {other:?}"),
        },
    }
}

// ---------------------------------------------------------------------------
// Walking the vectors
// ---------------------------------------------------------------------------

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/especificacao/vetores-de-teste")
}

/// Every `.json` file under `dir`, sorted, as `(relative path, parsed)`.
fn load(category: &str) -> Vec<(String, Json)> {
    let root = vectors_dir();
    let mut files = Vec::new();
    collect(&root.join(category), &mut files);
    files.sort();
    files
        .into_iter()
        .map(|file| {
            let relative = file
                .strip_prefix(&root)
                .expect("under the root")
                .to_string_lossy()
                .replace('\\', "/");
            let text = fs::read_to_string(&file).unwrap_or_else(|e| panic!("{relative}: {e}"));
            (relative, Parser::parse(&text))
        })
        .collect()
}

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    let entries = fs::read_dir(dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect(&path, out);
        } else if path.extension().is_some_and(|e| e == "json") {
            out.push(path);
        }
    }
}

/// Runs `check` on each vector and fails with every problem found.
fn run_all(category: &str, check: impl Fn(&str, &Json) -> Result<(), String>) -> usize {
    let vectors = load(category);
    let failures: Vec<String> = vectors
        .iter()
        .filter_map(|(path, vector)| check(path, vector).err().map(|e| format!("{path}: {e}")))
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    vectors.len()
}

// ---------------------------------------------------------------------------
// identidade/
// ---------------------------------------------------------------------------

fn bytes32(value: &Value) -> [u8; 32] {
    value
        .as_bytes()
        .expect("bytes")
        .try_into()
        .expect("32 bytes")
}

/// Looks a key up in a typed map value.
fn entry<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .as_map()
        .expect("a map")
        .iter()
        .find(|(k, _)| k == key)
        .map(|(_, v)| v)
        .unwrap_or_else(|| panic!("missing key {key:?}"))
}

fn check_identity(_path: &str, v: &Json) -> Result<(), String> {
    let function = v.field("funcao").str();
    let valid = v.field("valido").truthy();
    let input = v.field("entrada");
    let output = v.field("saida");
    let expected_error = v.field("erro");
    match function {
        "host_id" => {
            let key = bytes32(&typed(input));
            same(host_id(&key).as_str(), output.str())
        }
        "fingerprint" => {
            let key = bytes32(&typed(input));
            same(fingerprint(&key).as_str(), output.str())
        }
        "pairing_uri_format" => {
            let fields = typed(input);
            let uri = PairingUri {
                major: entry(&fields, "v").as_u64().expect("an integer"),
                relay: entry(&fields, "relay").as_text().expect("text").to_owned(),
                host_id: HostId::parse(entry(&fields, "host").as_text().expect("text"))
                    .map_err(|e| e.to_string())?,
                host_key: bytes32(entry(&fields, "key")),
                token: entry(&fields, "token")
                    .as_bytes()
                    .expect("bytes")
                    .try_into()
                    .expect("16 bytes"),
                name: entry(&fields, "name").as_text().expect("text").to_owned(),
            };
            same(uri.to_uri().as_str(), output.str())
        }
        "pairing_uri_parse" => match (PairingUri::parse(input.str()), valid) {
            (Ok(uri), true) => {
                let want = typed(output);
                same_value(&Value::Int(uri.major as i64), entry(&want, "v"))?;
                same(
                    uri.relay.as_str(),
                    entry(&want, "relay").as_text().expect("text"),
                )?;
                same(
                    uri.host_id.as_str(),
                    entry(&want, "host").as_text().expect("text"),
                )?;
                same_value(&Value::Bytes(uri.host_key.to_vec()), entry(&want, "key"))?;
                same_value(&Value::Bytes(uri.token.to_vec()), entry(&want, "token"))?;
                same(
                    uri.name.as_str(),
                    entry(&want, "name").as_text().expect("text"),
                )
            }
            (Err(e), false) => {
                same(expected_error.field("camada").str(), "uri")?;
                same(e.code(), expected_error.field("codigo").str())
            }
            (other, _) => Err(format!("unexpected result {other:?}")),
        },
        other => Err(format!("unknown function {other}")),
    }
}

fn same<T: PartialEq + std::fmt::Debug + ?Sized>(got: &T, want: &T) -> Result<(), String> {
    if got == want {
        Ok(())
    } else {
        Err(format!("got {got:?}, expected {want:?}"))
    }
}

fn same_value(got: &Value, want: &Value) -> Result<(), String> {
    same(got, want)
}

#[test]
fn identity_vectors() {
    let count = run_all("identidade", check_identity);
    assert!(count >= 10, "only {count} identity vectors");
}

// ---------------------------------------------------------------------------
// Value vectors: what every `envelope/` and `mensagens/` file shares
// ---------------------------------------------------------------------------

/// What the typed layers need to know about a value vector.
struct ValueCase<'a> {
    raiz: &'a str,
    bytes: Vec<u8>,
    valid: bool,
    reencode: Option<Vec<u8>>,
    error: &'a Json,
}

fn value_case(v: &Json) -> Result<ValueCase<'_>, String> {
    let bytes = decode_hex(v.field("cbor_hex").str()).map_err(|_| "cbor_hex is not hex")?;
    let valid = v.field("valido").truthy();
    let tree = v.field("valor");
    let decoded = cbor::decode(&bytes);

    // The generic layer: valor and cbor_hex say the same thing.
    if valid {
        if tree.is_null() {
            return Err("a valid vector with `valor: null`".to_owned());
        }
        let want = typed(tree);
        same_value(
            &decoded.map_err(|e| format!("cbor_hex does not decode: {e}"))?,
            &want,
        )?;
        if cbor::encode(&want) != bytes {
            return Err("encode(valor) differs from cbor_hex".to_owned());
        }
    } else if tree.is_null() {
        if decoded.is_ok() {
            return Err("`valor: null` but cbor_hex is an item".to_owned());
        }
    } else if let Ok(item) = decoded {
        same_value(&item, &typed(tree))?;
    }

    let reencode = match v.field("reencode_hex") {
        Json::Null => None,
        Json::Str(hex) => Some(decode_hex(hex).map_err(|_| "reencode_hex is not hex")?),
        other => return Err(format!("bad reencode_hex {other:?}")),
    };
    Ok(ValueCase {
        raiz: v.field("raiz").str(),
        bytes,
        valid,
        reencode,
        error: v.field("erro"),
    })
}

impl ValueCase<'_> {
    /// The bytes a valid vector must re-encode to.
    fn expected(&self) -> &[u8] {
        self.reencode.as_deref().unwrap_or(&self.bytes)
    }

    fn expect_refusal(&self, layer: &str, code: &str) -> Result<(), String> {
        same(self.error.field("camada").str(), layer)?;
        same(self.error.field("codigo").str(), code)
    }
}

// ---------------------------------------------------------------------------
// envelope/
// ---------------------------------------------------------------------------

fn bstr(bytes: &[u8]) -> Value {
    Value::Bytes(bytes.to_vec())
}

fn int(n: u64) -> Value {
    Value::int(n as i64).expect("within the domain")
}

/// The CBOR item a host envelope stands for, written independently of the
/// codec, to compare against `valor`.
fn host_item(envelope: &HostEnvelope) -> Value {
    let channel = |c: &ChannelId| int(c.0);
    Value::Array(match envelope {
        HostEnvelope::Challenge { nonce } => vec![int(0), bstr(nonce)],
        HostEnvelope::Register {
            routing_key,
            signature,
        } => vec![int(1), bstr(routing_key), bstr(signature)],
        HostEnvelope::Registered { host_id } => {
            vec![int(2), Value::Text(host_id.as_str().to_owned())]
        }
        HostEnvelope::ChannelOpened { channel: c } => vec![int(3), channel(c)],
        HostEnvelope::ChannelData {
            channel: c,
            payload,
        } => {
            vec![int(4), channel(c), bstr(payload.as_bytes())]
        }
        HostEnvelope::ChannelClosed { channel: c, reason } => {
            vec![int(5), channel(c), int(reason.code())]
        }
        HostEnvelope::CloseChannel { channel: c, reason } => {
            vec![int(6), channel(c), int(reason.code())]
        }
    })
}

fn client_item(envelope: &ClientEnvelope) -> Value {
    Value::Array(match envelope {
        ClientEnvelope::Data { payload } => vec![int(16), bstr(payload.as_bytes())],
        ClientEnvelope::HostUnavailable => vec![int(17)],
        ClientEnvelope::Closed { reason } => vec![int(18), int(reason.code())],
    })
}

fn start_item(start: &HandshakeStart) -> Value {
    Value::Array(vec![int(start.kind.code()), bstr(&start.msg1)])
}

/// The close code a relay would use for an envelope error.
fn envelope_code(error: &EnvelopeError) -> &'static str {
    match error {
        EnvelopeError::FrameTooLarge => "1009",
        _ => "4004",
    }
}

fn check_envelope(_path: &str, v: &Json) -> Result<(), String> {
    let case = value_case(v)?;
    let want = (!v.field("valor").is_null()).then(|| typed(v.field("valor")));
    let frame: bytes::Bytes = case.bytes.clone().into();
    match case.raiz {
        "host-envelope" => match (decode_host(frame), case.valid) {
            (Ok(envelope), true) => {
                same(&encode_host(&envelope)[..], case.expected())?;
                same_value(&host_item(&envelope), &want.expect("valor"))
            }
            (Err(e), false) => case.expect_refusal("envelope", envelope_code(&e)),
            (other, _) => Err(format!("unexpected result {other:?}")),
        },
        "client-envelope" => match (decode_client(frame), case.valid) {
            (Ok(envelope), true) => {
                same(&encode_client(&envelope)[..], case.expected())?;
                same_value(&client_item(&envelope), &want.expect("valor"))
            }
            (Err(e), false) => case.expect_refusal("envelope", envelope_code(&e)),
            (other, _) => Err(format!("unexpected result {other:?}")),
        },
        "handshake-start" => match (decode_handshake_start(frame), case.valid) {
            (Ok(start), true) => {
                same(&encode_handshake_start(&start)[..], case.expected())?;
                same_value(&start_item(&start), &want.expect("valor"))
            }
            (Err(e), false) => case.expect_refusal("envelope", envelope_code(&e)),
            (other, _) => Err(format!("unexpected result {other:?}")),
        },
        other => Err(format!("unexpected root {other} in envelope/")),
    }
}

#[test]
fn envelope_vectors() {
    let count = run_all("envelope", check_envelope);
    assert!(count >= 30, "only {count} envelope vectors");
}

// ---------------------------------------------------------------------------
// mensagens/
// ---------------------------------------------------------------------------

#[cfg(feature = "message")]
mod messages {
    use super::*;
    use porecatu_protocol::message::{
        DecodeError, Direction, ErrorCode, PairRequest, decode, encode,
    };

    /// Folder of `mensagens/` and the message type number (`None`: the
    /// `pair-request`, a bare map).
    const FOLDERS: [(&str, Option<u64>); 28] = [
        ("hello", Some(0)),
        ("welcome", Some(1)),
        ("incompatible", Some(2)),
        ("goodbye", Some(3)),
        ("workspace", Some(10)),
        ("profiles", Some(11)),
        ("theme", Some(12)),
        ("view-tab", Some(13)),
        ("subscribe", Some(20)),
        ("unsubscribe", Some(21)),
        ("grid-snapshot", Some(22)),
        ("grid-diff", Some(23)),
        ("grid-ack", Some(24)),
        ("scrollback-request", Some(25)),
        ("scrollback-page", Some(26)),
        ("subscription-ended", Some(27)),
        ("key", Some(30)),
        ("text-input", Some(31)),
        ("paste", Some(32)),
        ("action", Some(40)),
        ("action-result", Some(41)),
        ("confirm-request", Some(42)),
        ("confirm", Some(43)),
        ("bell", Some(50)),
        ("pair-accepted", Some(60)),
        ("pair-rejected", Some(61)),
        ("error", Some(70)),
        ("pair-request", None),
    ];

    /// The folder of `mensagens/<folder>/<file>.json`.
    fn folder_of(path: &str) -> &str {
        path.split('/').nth(1).expect("a folder under mensagens/")
    }

    fn check_message(path: &str, v: &Json) -> Result<(), String> {
        let case = value_case(v)?;
        let folder = folder_of(path);
        let (_, code) = FOLDERS
            .iter()
            .find(|(name, _)| *name == folder)
            .ok_or_else(|| format!("unknown folder {folder}"))?;

        // The folder and the item agree on the type.
        match (code, case.raiz) {
            (Some(_), "message") | (None, "pair-request") => {}
            (_, other) => return Err(format!("root {other} in folder {folder}")),
        }
        if let (Some(code), false) = (code, v.field("valor").is_null()) {
            let item = typed(v.field("valor"));
            let first = item.as_array().ok().and_then(|items| items.first());
            if first.and_then(|f| f.as_u64().ok()) != Some(*code) {
                return Err(format!("valor does not start with the type {code}"));
            }
        }

        if code.is_none() {
            return check_pair_request(&case);
        }
        let results: Vec<Result<_, DecodeError>> =
            [Direction::HostToClient, Direction::ClientToHost]
                .into_iter()
                .map(|from| decode(&case.bytes, from))
                .collect();
        if case.valid {
            let decoded: Vec<_> = results.iter().filter_map(|r| r.as_ref().ok()).collect();
            let Some(message) = decoded.first() else {
                return Err(format!("no direction decodes it: {results:?}"));
            };
            if decoded.iter().any(|m| m != message) {
                return Err("the directions decode to different messages".to_owned());
            }
            if message.type_code() != code.expect("a message type") {
                return Err("decoded to another type".to_owned());
            }
            same(&encode(message)[..], case.expected())
        } else {
            if let Some(Ok(_)) = results.iter().find(|r| r.is_ok()) {
                return Err("a vector marked invalid decodes".to_owned());
            }
            // At least one direction refuses it for its content, not only
            // because of who sends it.
            let content = results
                .iter()
                .filter_map(|r| r.as_ref().err())
                .find(|e| !matches!(e, DecodeError::WrongDirection(_)))
                .ok_or("refused only for its direction")?;
            same(&content.error_code(), &ErrorCode::Protocol)?;
            case.expect_refusal("mensagem", "protocol")
        }
    }

    fn check_pair_request(case: &ValueCase<'_>) -> Result<(), String> {
        match (PairRequest::decode(&case.bytes), case.valid) {
            (Ok(request), true) => {
                let again = request.encode().map_err(|e| e.to_string())?;
                same(&again[..], case.expected())
            }
            (Err(e), false) => {
                same(&e.error_code(), &ErrorCode::Protocol)?;
                case.expect_refusal("mensagem", "protocol")
            }
            (other, _) => Err(format!("unexpected result {other:?}")),
        }
    }

    #[test]
    fn message_vectors() {
        let vectors = load("mensagens");
        let count = run_all("mensagens", check_message);
        assert_eq!(count, vectors.len());

        // Every message has the four cases of the README table that do not
        // depend on its body, and a refusal for each of its keys.
        for (folder, _) in FOLDERS {
            for file in ["minimo", "completo", "chave-desconhecida", "nao-canonico"] {
                let wanted = format!("mensagens/{folder}/{file}.json");
                assert!(
                    vectors.iter().any(|(path, _)| *path == wanted),
                    "missing {wanted}"
                );
            }
            assert!(
                vectors
                    .iter()
                    .any(|(path, _)| path.starts_with(&format!("mensagens/{folder}/sem-"))),
                "no `sem-<chave>` vector in {folder}"
            );
        }
        assert!(count >= 200, "only {count} message vectors");
    }

    /// The unknown-key vector of every message re-encodes to its minimal one.
    #[test]
    fn unknown_key_re_encodes_to_the_minimal_vector() {
        let vectors = load("mensagens");
        for (folder, _) in FOLDERS {
            let get = |file: &str| {
                let wanted = format!("mensagens/{folder}/{file}.json");
                vectors
                    .iter()
                    .find(|(path, _)| *path == wanted)
                    .map(|(_, v)| v)
                    .unwrap_or_else(|| panic!("missing {wanted}"))
            };
            let unknown = get("chave-desconhecida");
            let minimal = get("minimo");
            assert_eq!(
                unknown.field("reencode_hex").str(),
                minimal.field("cbor_hex").str(),
                "{folder}"
            );
            assert_ne!(
                unknown.field("cbor_hex").str(),
                minimal.field("cbor_hex").str(),
                "{folder}"
            );
        }
    }
}

// ---------------------------------------------------------------------------
// noise/, registros/ and sessoes/
// ---------------------------------------------------------------------------

#[cfg(feature = "session")]
mod wire {
    use super::*;

    fn hex(text: &str) -> Vec<u8> {
        decode_hex(text).expect("lowercase hex")
    }

    fn array(json: &Json) -> &[Json] {
        match json {
            Json::Arr(items) => items,
            other => panic!("not an array: {other:?}"),
        }
    }

    #[cfg(all(feature = "message", feature = "test-vectors"))]
    fn uint(json: &Json) -> u64 {
        match json {
            Json::Int(i) => u64::try_from(*i).expect("not negative"),
            other => panic!("not an integer: {other:?}"),
        }
    }

    // -----------------------------------------------------------------------
    // noise/cacophony-*.json: the vectors of the cacophony project, replayed
    // on `snow` itself (the Noise implementation under the crate)
    // -----------------------------------------------------------------------

    fn replay_cacophony(v: &Json) -> Result<(), String> {
        use snow::Builder;
        use snow::params::NoiseParams;

        let err = |e: snow::Error| format!("{e:?}");
        let name = v.field("protocol_name").str();
        let params: NoiseParams = name.parse().map_err(|e| format!("{e:?}"))?;
        let init_prologue = hex(v.field("init_prologue").str());
        let init_static = hex(v.field("init_static").str());
        let init_ephemeral = hex(v.field("init_ephemeral").str());
        let resp_prologue = hex(v.field("resp_prologue").str());
        let resp_static = hex(v.field("resp_static").str());
        let resp_ephemeral = hex(v.field("resp_ephemeral").str());
        let remote = v
            .get("init_remote_static")
            .filter(|j| !j.is_null())
            .map(|j| hex(j.str()));

        let mut initiator = Builder::new(params.clone())
            .prologue(&init_prologue)
            .map_err(err)?
            .local_private_key(&init_static)
            .map_err(err)?
            .fixed_ephemeral_key_for_testing_only(&init_ephemeral);
        if let Some(remote) = &remote {
            initiator = initiator.remote_public_key(remote).map_err(err)?;
        }
        let mut initiator = initiator.build_initiator().map_err(err)?;
        let mut responder = Builder::new(params)
            .prologue(&resp_prologue)
            .map_err(err)?
            .local_private_key(&resp_static)
            .map_err(err)?
            .fixed_ephemeral_key_for_testing_only(&resp_ephemeral)
            .build_responder()
            .map_err(err)?;

        let handshake_len = if name == "Noise_XX_25519_ChaChaPoly_BLAKE2s" {
            3
        } else {
            2
        };
        let messages = array(v.field("messages"));
        let mut written = vec![0u8; 65_535];
        let mut read = vec![0u8; 65_535];
        for (index, message) in messages.iter().enumerate().take(handshake_len) {
            let payload = hex(message.field("payload").str());
            let wanted = hex(message.field("ciphertext").str());
            let (writer, reader) = if index % 2 == 0 {
                (&mut initiator, &mut responder)
            } else {
                (&mut responder, &mut initiator)
            };
            let n = writer.write_message(&payload, &mut written).map_err(err)?;
            same(&written[..n], &wanted[..]).map_err(|e| format!("message {index}: {e}"))?;
            let m = reader.read_message(&wanted, &mut read).map_err(err)?;
            same(&read[..m], &payload[..]).map_err(|e| format!("message {index}: {e}"))?;
        }
        if let Some(hash) = v.get("handshake_hash").filter(|j| !j.is_null()) {
            let wanted = hex(hash.str());
            same(initiator.get_handshake_hash(), &wanted[..])?;
            same(responder.get_handshake_hash(), &wanted[..])?;
        }
        let mut initiator = initiator.into_transport_mode().map_err(err)?;
        let mut responder = responder.into_transport_mode().map_err(err)?;
        for (index, message) in messages.iter().enumerate().skip(handshake_len) {
            let payload = hex(message.field("payload").str());
            let wanted = hex(message.field("ciphertext").str());
            let (writer, reader) = if index % 2 == 0 {
                (&mut initiator, &mut responder)
            } else {
                (&mut responder, &mut initiator)
            };
            let n = writer.write_message(&payload, &mut written).map_err(err)?;
            same(&written[..n], &wanted[..]).map_err(|e| format!("message {index}: {e}"))?;
            let m = reader.read_message(&wanted, &mut read).map_err(err)?;
            same(&read[..m], &payload[..]).map_err(|e| format!("message {index}: {e}"))?;
        }
        Ok(())
    }

    fn check_cacophony(file: &Json) -> Result<(), String> {
        same(file.field("formato").str(), "noise-cacophony")?;
        let vectors = array(file.field("vectors"));
        if vectors.is_empty() {
            return Err("no vectors".to_owned());
        }
        for (index, v) in vectors.iter().enumerate() {
            replay_cacophony(v).map_err(|e| format!("vector {index}: {e}"))?;
        }
        Ok(())
    }

    // -----------------------------------------------------------------------
    // The vectors with the Porecatu prologue and fixed keys: they need the
    // `test-vectors` feature (fixed ephemerals). `cargo test --workspace`
    // turns it on (the `vectors` tool depends on it); a bare
    // `cargo test -p porecatu-protocol` skips them.
    // -----------------------------------------------------------------------

    #[cfg(all(feature = "message", feature = "test-vectors"))]
    mod fixed {
        use super::*;
        use blake2::{Blake2s256, Digest};
        use bytes::Bytes;
        use porecatu_protocol::envelope::{
            ChannelId, ClientEnvelope, CloseReason, HandshakeStart, HandshakeStartKind,
            HostEnvelope, Payload,
        };
        use porecatu_protocol::message::{self, Direction};
        use porecatu_protocol::session::{
            ClientHandshake, ClientStep, HandshakeError, HandshakeKind, HostHandshake, HostStep,
            PairingToken, RecordError, RekeyPolicy, Session, StaticKeypair, Transport, prologue,
        };

        struct Keys {
            host_static: [u8; 32],
            host_ephemeral: [u8; 32],
            client_static: [u8; 32],
            client_ephemeral: [u8; 32],
        }

        fn keys_of(v: &Json) -> Keys {
            let keys = v.field("chaves");
            let key = |name: &str| bytes32(&typed(keys.field(name)));
            Keys {
                host_static: key("host_estatica"),
                host_ephemeral: key("host_efemera"),
                client_static: key("cliente_estatica"),
                client_ephemeral: key("cliente_efemera"),
            }
        }

        fn handshake_code(error: &HandshakeError) -> &'static str {
            match error {
                HandshakeError::HostKeyMismatch => "host-key-mismatch",
                HandshakeError::DhZero => "dh-zero",
                HandshakeError::Decrypt => "decrypt",
                _ => "other",
            }
        }

        fn record_code(error: &RecordError) -> &'static str {
            match error {
                RecordError::ReservedFlags => "reserved-flag",
                RecordError::MessageTooLong => "too-large",
                RecordError::Transport(_) => "decrypt",
                _ => "other",
            }
        }

        fn bytes_of(value: &Value) -> Vec<u8> {
            value.as_bytes().expect("a bstr").to_vec()
        }

        fn blake2s(data: &[u8]) -> String {
            porecatu_protocol::encoding::encode_hex(&Blake2s256::digest(data))
        }

        fn pattern(len: usize) -> Vec<u8> {
            (0..len).map(|i| (i % 251) as u8).collect()
        }

        // ---- noise/ -------------------------------------------------------

        enum HostSide {
            Pending(Box<HostHandshake>),
            Done(Transport),
        }

        pub fn noise(v: &Json) -> Result<(), String> {
            let keys = keys_of(v);
            let id = v.field("host_id").str();
            same(&hex(v.field("prologo_hex").str())[..], &prologue(id)[..])?;
            let kind = match v.field("padrao").str() {
                "XX" => HandshakeKind::Pair,
                "IK" => HandshakeKind::Connect,
                other => return Err(format!("unknown pattern {other}")),
            };
            let host_key = bytes32(&typed(v.field("chave_do_host")));
            // (side, payload, wire) of each message.
            let messages: Vec<(String, Vec<u8>, Vec<u8>)> = array(v.field("mensagens"))
                .iter()
                .map(|m| {
                    (
                        m.field("de").str().to_owned(),
                        bytes_of(&typed(m.field("payload"))),
                        hex(m.field("hex").str()),
                    )
                })
                .collect();
            let valid = v.field("valido").truthy();
            let (who, code) = if valid {
                (String::new(), String::new())
            } else {
                same(v.field("erro").field("camada").str(), "handshake")?;
                (
                    v.field("quem_falha").str().to_owned(),
                    v.field("erro").field("codigo").str().to_owned(),
                )
            };
            let client_pair = StaticKeypair::from_private(keys.client_static);
            let host_pair = StaticKeypair::from_private(keys.host_static);

            let started = match kind {
                HandshakeKind::Pair => ClientHandshake::pair_with_ephemeral(
                    &client_pair,
                    &host_key,
                    id,
                    &keys.client_ephemeral,
                ),
                HandshakeKind::Connect => ClientHandshake::connect_with_ephemeral(
                    &client_pair,
                    &host_key,
                    id,
                    &keys.client_ephemeral,
                ),
            };
            if !valid && who == "cliente" && messages.is_empty() {
                return match started {
                    Err(e) => same(handshake_code(&e), code.as_str()),
                    Ok(_) => Err("the client started but must refuse".to_owned()),
                };
            }
            // The one case in which the client is not the author of `msg1`:
            // the host refuses a hand-made one.
            let (client, msg1) = if !valid && who == "host" {
                (None, messages[0].2.clone())
            } else {
                let (client, msg1) = started.map_err(|e| e.to_string())?;
                same(&msg1[..], &messages[0].2[..]).map_err(|e| format!("msg1: {e}"))?;
                (Some(client), msg1)
            };

            let answered = HostHandshake::respond_with_ephemeral(
                kind,
                &host_pair,
                id,
                &msg1,
                &keys.host_ephemeral,
            );
            if !valid && who == "host" {
                return match answered {
                    Err(e) => same(handshake_code(&e), code.as_str()),
                    Ok(_) => Err("the host answered but must refuse".to_owned()),
                };
            }
            let (msg2, host_side) = match answered.map_err(|e| e.to_string())? {
                HostStep::Pair { msg2, pending } => (msg2, HostSide::Pending(Box::new(pending))),
                HostStep::Connect { msg2, transport } => (msg2, HostSide::Done(transport)),
            };
            same(&msg2[..], &messages[1].2[..]).map_err(|e| format!("msg2: {e}"))?;

            let mut client = client.ok_or("no client")?;
            let read = client.read_message2(&msg2);
            if !valid {
                return match read {
                    Err(e) => same(handshake_code(&e), code.as_str()),
                    Ok(_) => Err("the client read msg2 but must refuse".to_owned()),
                };
            }
            let wanted_hash = hex(v.field("handshake_hash").str());
            let (client_hash, host_hash, host_sees) =
                match (read.map_err(|e| e.to_string())?, host_side) {
                    (ClientStep::Established(client_t), HostSide::Done(host_t)) => (
                        client_t.handshake_hash().to_vec(),
                        host_t.handshake_hash().to_vec(),
                        host_t.remote_static(),
                    ),
                    (ClientStep::NeedsPairRequest, HostSide::Pending(pending)) => {
                        let payload = &messages[2].1;
                        let (msg3, client_t) =
                            client.write_message3(payload).map_err(|e| e.to_string())?;
                        same(&msg3[..], &messages[2].2[..]).map_err(|e| format!("msg3: {e}"))?;
                        let (read_payload, device, host_t) =
                            pending.read_message3(&msg3).map_err(|e| e.to_string())?;
                        same(&read_payload, payload)?;
                        (
                            client_t.handshake_hash().to_vec(),
                            host_t.handshake_hash().to_vec(),
                            Some(device),
                        )
                    }
                    _ => return Err("the two sides are in different phases".to_owned()),
                };
            same(&client_hash, &wanted_hash).map_err(|e| format!("client hash: {e}"))?;
            same(&host_hash, &wanted_hash).map_err(|e| format!("host hash: {e}"))?;
            same(&host_sees, &Some(client_pair.public()))
        }

        // ---- registros/ ---------------------------------------------------

        /// Two transports linked by the `IK` handshake of the vector's keys.
        fn transports(v: &Json) -> (Transport, Transport) {
            let keys = keys_of(v);
            let id = v.field("host_id").str();
            let client = StaticKeypair::from_private(keys.client_static);
            let host = StaticKeypair::from_private(keys.host_static);
            let (mut handshake, msg1) = ClientHandshake::connect_with_ephemeral(
                &client,
                &host.public(),
                id,
                &keys.client_ephemeral,
            )
            .expect("the client starts");
            let HostStep::Connect {
                msg2,
                transport: host_t,
            } = HostHandshake::respond_with_ephemeral(
                HandshakeKind::Connect,
                &host,
                id,
                &msg1,
                &keys.host_ephemeral,
            )
            .expect("the host answers")
            else {
                panic!("IK gives HostStep::Connect");
            };
            let Ok(ClientStep::Established(client_t)) = handshake.read_message2(&msg2) else {
                panic!("IK is established after msg2");
            };
            (client_t, host_t)
        }

        pub fn records(v: &Json) -> Result<(), String> {
            let (client_t, host_t) = transports(v);
            let policy = RekeyPolicy {
                max_records: uint(v.field("politica").field("max_records")),
                max_age_ms: uint(v.field("politica").field("max_age_ms")),
            };
            let handshake_ms = uint(v.field("handshake_ms"));
            let mut client = Session::with_policy(client_t, policy, Some(handshake_ms));
            let mut host = Session::with_policy(host_t, policy, Some(handshake_ms));
            let valid = v.field("valido").truthy();
            let expected_code = v.field("erro").get("codigo").map(|j| j.str().to_owned());
            if valid {
                same(v.field("erro"), &Json::Null)?;
            } else {
                same(v.field("erro").field("camada").str(), "registro")?;
            }

            let steps = array(v.field("passos"));
            for (index, step) in steps.iter().enumerate() {
                let at = |e: String| format!("step {index}: {e}");
                let last = index + 1 == steps.len();
                let from_client = step.field("de").str() == "cliente";
                let now = uint(step.field("now_ms"));
                let plain = step.field("texto_claro");
                same(plain.field("padrao").str(), "i mod 251").map_err(at)?;
                let message = pattern(uint(plain.field("tamanho")) as usize);
                same(&blake2s(&message)[..], plain.field("blake2s").str()).map_err(at)?;
                let hashes: Vec<&str> = array(step.field("registros_blake2s"))
                    .iter()
                    .map(Json::str)
                    .collect();
                let full: Option<Vec<Vec<u8>>> = match step.field("registros_hex") {
                    Json::Null => None,
                    list => Some(array(list).iter().map(|r| hex(r.str())).collect()),
                };
                let (sender, receiver) = if from_client {
                    (&mut client, &mut host)
                } else {
                    (&mut host, &mut client)
                };

                if step.field("forjado").truthy() {
                    // Built below the record layer: only the receiver runs.
                    let records = full.ok_or_else(|| at("forged without records".to_owned()))?;
                    let mut refusal = None;
                    for record in &records {
                        if let Err(e) = receiver.open(record, now) {
                            refusal = Some(record_code(&e));
                            break;
                        }
                    }
                    let got = refusal.ok_or_else(|| at("the receiver accepted it".to_owned()))?;
                    same(&Some(got), &expected_code.as_deref()).map_err(at)?;
                    continue;
                }

                let sealed = sender.seal(&message, now);
                if !valid && last && expected_code.as_deref() == Some("too-large") {
                    // The sender refuses and nothing goes out.
                    let got = sealed.err().map(|e| record_code(&e));
                    same(&got, &Some("too-large")).map_err(at)?;
                    same(&hashes.len(), &0).map_err(at)?;
                    continue;
                }
                let records = sealed.map_err(|e| at(format!("seal: {e:?}")))?;
                same(&records.len(), &hashes.len()).map_err(at)?;
                for (position, record) in records.iter().enumerate() {
                    same(&blake2s(record)[..], hashes[position]).map_err(at)?;
                    if let Some(full) = &full {
                        same(record, &full[position]).map_err(at)?;
                    }
                }
                let last_record = records.len() - 1;
                for (position, record) in records.iter().enumerate() {
                    let out = receiver
                        .open(record, now)
                        .map_err(|e| at(format!("open: {e:?}")))?;
                    if position == last_record {
                        same(&out, &Some(message.clone())).map_err(at)?;
                    } else if out.is_some() {
                        return Err(at("a fragment completed a message".to_owned()));
                    }
                }
            }
            Ok(())
        }

        // ---- sessoes/ -----------------------------------------------------

        /// What the host must answer next, by the rules of 02 and 03.
        enum Decision {
            Pairing { token_ok: bool },
            NotPaired,
            Hello { same_version: bool },
        }

        fn version_of(item: &Value) -> Result<[u64; 2], String> {
            let body = &item.as_array().map_err(|e| e.to_string())?[1];
            let version = entry(body, "version")
                .as_array()
                .map_err(|e| e.to_string())?;
            Ok([
                version[0].as_u64().map_err(|e| e.to_string())?,
                version[1].as_u64().map_err(|e| e.to_string())?,
            ])
        }

        fn type_of(item: &Value) -> u64 {
            item.as_array().expect("an item")[0]
                .as_u64()
                .expect("a type")
        }

        impl Decision {
            fn check(&self, item: &Value, host_version: [u64; 2]) -> Result<(), String> {
                let kind = type_of(item);
                let body = &item.as_array().map_err(|e| e.to_string())?[1];
                match self {
                    Decision::Pairing { token_ok: true } => same(&kind, &60),
                    Decision::Pairing { token_ok: false } => {
                        same(&kind, &61)?;
                        same(
                            &entry(body, "reason").as_u64().map_err(|e| e.to_string())?,
                            &0,
                        )
                    }
                    Decision::NotPaired => {
                        same(&kind, &70)?;
                        same(
                            &entry(body, "code").as_u64().map_err(|e| e.to_string())?,
                            &1,
                        )
                    }
                    Decision::Hello { same_version: true } => {
                        same(&kind, &1)?;
                        same(&version_of(item)?, &host_version)
                    }
                    Decision::Hello {
                        same_version: false,
                    } => {
                        same(&kind, &2)?;
                        same(&version_of(item)?, &host_version)
                    }
                }
            }
        }

        fn frame_of_client(payload: Vec<u8>) -> Vec<u8> {
            porecatu_protocol::envelope::encode_client(&ClientEnvelope::Data {
                payload: Payload::from_bytes(Bytes::from(payload)),
            })
        }

        fn frame_of_host(channel: u64, payload: Vec<u8>) -> Vec<u8> {
            porecatu_protocol::envelope::encode_host(&HostEnvelope::ChannelData {
                channel: ChannelId(channel),
                payload: Payload::from_bytes(Bytes::from(payload)),
            })
        }

        /// The fields of a step, decoded.
        struct Step {
            from_client: bool,
            now: u64,
            item: Option<Value>,
            records: Vec<Vec<u8>>,
            frames: Vec<Vec<u8>>,
        }

        fn step_of(raw: &Json) -> Step {
            Step {
                from_client: raw.field("de").str() == "cliente",
                now: uint(raw.field("now_ms")),
                item: (!raw.field("mensagem").is_null()).then(|| typed(raw.field("mensagem"))),
                records: array(raw.field("registros_hex"))
                    .iter()
                    .map(|r| hex(r.str()))
                    .collect(),
                frames: array(raw.field("envelope_hex"))
                    .iter()
                    .map(|r| hex(r.str()))
                    .collect(),
            }
        }

        pub fn session(v: &Json) -> Result<(), String> {
            let keys = keys_of(v);
            let id = v.field("host_id").str();
            let channel = uint(v.field("canal"));
            let host_version = {
                let version = array(v.field("versao"));
                [uint(&version[0]), uint(&version[1])]
            };
            let kind = match v.field("handshake").str() {
                "XX" => HandshakeKind::Pair,
                "IK" => HandshakeKind::Connect,
                other => return Err(format!("unknown handshake {other}")),
            };
            let client_pair = StaticKeypair::from_private(keys.client_static);
            let host_pair = StaticKeypair::from_private(keys.host_static);
            let host_key = host_pair.public();
            let token_host: Option<[u8; 16]> = (!v.field("token_host").is_null()).then(|| {
                bytes_of(&typed(v.field("token_host")))
                    .try_into()
                    .expect("16 bytes")
            });
            let paired: Vec<[u8; 32]> = array(v.field("pareados"))
                .iter()
                .map(|k| bytes32(&typed(k)))
                .collect();
            let steps: Vec<Step> = array(v.field("passos")).iter().map(step_of).collect();
            let handshake_len = if kind == HandshakeKind::Pair { 3 } else { 2 };
            if steps.len() <= handshake_len {
                return Err("shorter than its handshake".to_owned());
            }

            // Step 0: the client writes msg1, inside a handshake-start.
            let (mut client, msg1) = match kind {
                HandshakeKind::Pair => ClientHandshake::pair_with_ephemeral(
                    &client_pair,
                    &host_key,
                    id,
                    &keys.client_ephemeral,
                ),
                HandshakeKind::Connect => ClientHandshake::connect_with_ephemeral(
                    &client_pair,
                    &host_key,
                    id,
                    &keys.client_ephemeral,
                ),
            }
            .map_err(|e| e.to_string())?;
            let start = porecatu_protocol::envelope::encode_handshake_start(&HandshakeStart {
                kind: if kind == HandshakeKind::Pair {
                    HandshakeStartKind::Pair
                } else {
                    HandshakeStartKind::Connect
                },
                msg1: Bytes::from(msg1.clone()),
            });
            let first = &steps[0];
            if !first.from_client || first.item.is_some() {
                return Err("step 0 is the client's msg1".to_owned());
            }
            same(&first.records, &vec![msg1.clone()]).map_err(|e| format!("msg1: {e}"))?;
            same(&first.frames, &vec![frame_of_client(start)])
                .map_err(|e| format!("frame 0: {e}"))?;

            // Step 1: the host answers with msg2.
            let (msg2, host_side) = match HostHandshake::respond_with_ephemeral(
                kind,
                &host_pair,
                id,
                &msg1,
                &keys.host_ephemeral,
            )
            .map_err(|e| e.to_string())?
            {
                HostStep::Pair { msg2, pending } => (msg2, HostSide::Pending(Box::new(pending))),
                HostStep::Connect { msg2, transport } => (msg2, HostSide::Done(transport)),
            };
            let second = &steps[1];
            if second.from_client || second.item.is_some() {
                return Err("step 1 is the host's msg2".to_owned());
            }
            same(&second.records, &vec![msg2.clone()]).map_err(|e| format!("msg2: {e}"))?;
            same(&second.frames, &vec![frame_of_host(channel, msg2.clone())])
                .map_err(|e| format!("frame 1: {e}"))?;

            match (
                client.read_message2(&msg2).map_err(|e| e.to_string())?,
                host_side,
            ) {
                // IK: both transports exist after msg2. A device that is not
                // in the list gets `error { not-paired }` first.
                (ClientStep::Established(client_t), HostSide::Done(host_t)) => {
                    same(&host_t.remote_static(), &Some(client_pair.public()))?;
                    let owed =
                        (!paired.contains(&client_pair.public())).then_some(Decision::NotPaired);
                    replay_rest(
                        v,
                        &steps,
                        2,
                        Session::new(client_t, Some(second.now)),
                        Session::new(host_t, Some(second.now)),
                        channel,
                        host_version,
                        owed,
                    )
                }
                // XX: msg3 carries the pair-request.
                (ClientStep::NeedsPairRequest, HostSide::Pending(pending)) => {
                    let third = &steps[2];
                    let request = third
                        .item
                        .as_ref()
                        .ok_or("step 2 carries the pair-request")?;
                    let request_bytes = cbor::encode(request);
                    let (msg3, client_t) = client
                        .write_message3(&request_bytes)
                        .map_err(|e| e.to_string())?;
                    same(&third.records, &vec![msg3.clone()]).map_err(|e| format!("msg3: {e}"))?;
                    same(&third.frames, &vec![frame_of_client(msg3.clone())])
                        .map_err(|e| format!("frame 2: {e}"))?;
                    let (read, device, host_t) =
                        pending.read_message3(&msg3).map_err(|e| e.to_string())?;
                    same(&read, &request_bytes)?;
                    same(&device, &client_pair.public())?;
                    // The host's decision about the token.
                    let presented = bytes_of(entry(request, "token"));
                    let token_ok = token_host.is_some_and(|held| {
                        PairingToken::new(held, 0).matches_and_consume(&presented, third.now)
                    });
                    replay_rest(
                        v,
                        &steps,
                        3,
                        Session::new(client_t, Some(third.now)),
                        Session::new(host_t, Some(third.now)),
                        channel,
                        host_version,
                        Some(Decision::Pairing { token_ok }),
                    )
                }
                _ => Err("the two sides are in different phases".to_owned()),
            }
        }

        /// The steps after the handshake. `owed` is the answer the host owes
        /// right after it.
        #[allow(clippy::too_many_arguments)]
        fn replay_rest(
            v: &Json,
            steps: &[Step],
            from: usize,
            mut client: Session,
            mut host: Session,
            channel: u64,
            host_version: [u64; 2],
            owed: Option<Decision>,
        ) -> Result<(), String> {
            let mut decision = owed;
            let mut closed = false;
            let mut last_host_item: Option<Value> = None;
            for (offset, step) in steps[from..].iter().enumerate() {
                let at = |e: String| format!("step {}: {e}", from + offset);
                if closed {
                    return Err(at("a step after the close".to_owned()));
                }
                if step.records.is_empty() {
                    // The host closes the channel.
                    let [frame] = step.frames.as_slice() else {
                        return Err(at("a close is one frame".to_owned()));
                    };
                    let envelope = porecatu_protocol::envelope::decode_host(frame.clone().into())
                        .map_err(|e| at(e.to_string()))?;
                    same(
                        &envelope,
                        &HostEnvelope::CloseChannel {
                            channel: ChannelId(channel),
                            reason: CloseReason::Normal,
                        },
                    )
                    .map_err(at)?;
                    same(&step.from_client, &false).map_err(at)?;
                    closed = true;
                    continue;
                }
                let item = step
                    .item
                    .as_ref()
                    .ok_or_else(|| at("a message step needs `mensagem`".to_owned()))?;
                let wire = cbor::encode(item);
                let (sender, receiver, direction) = if step.from_client {
                    (&mut client, &mut host, Direction::ClientToHost)
                } else {
                    (&mut host, &mut client, Direction::HostToClient)
                };
                let sealed = sender
                    .seal(&wire, step.now)
                    .map_err(|e| at(format!("{e:?}")))?;
                same(&sealed, &step.records).map_err(at)?;
                let frames: Vec<Vec<u8>> = sealed
                    .iter()
                    .map(|r| {
                        if step.from_client {
                            frame_of_client(r.clone())
                        } else {
                            frame_of_host(channel, r.clone())
                        }
                    })
                    .collect();
                same(&frames, &step.frames).map_err(at)?;
                let last = sealed.len() - 1;
                for (position, record) in sealed.iter().enumerate() {
                    let out = receiver
                        .open(record, step.now)
                        .map_err(|e| at(format!("{e:?}")))?;
                    if position == last {
                        same(&out, &Some(wire.clone())).map_err(at)?;
                    } else if out.is_some() {
                        return Err(at("a fragment completed a message".to_owned()));
                    }
                }
                let decoded =
                    message::decode(&wire, direction).map_err(|e| at(format!("{e:?}")))?;
                same(&message::encode(&decoded), &wire).map_err(at)?;

                // The rules of the host's answers.
                if step.from_client {
                    if type_of(item) == 0 {
                        decision = Some(Decision::Hello {
                            same_version: version_of(item).map_err(at)? == host_version,
                        });
                    }
                } else {
                    if let Some(owed) = decision.take() {
                        owed.check(item, host_version).map_err(at)?;
                    }
                    last_host_item = Some(item.clone());
                }
            }

            // The final state follows from the host's last message.
            let state = v.field("resultado");
            let result = state.field("estado").str();
            same(&closed, &(result == "fechada"))?;
            if closed {
                let last = last_host_item.ok_or("closed without a host message")?;
                let code = match type_of(&last) {
                    61 => "token-invalid",
                    70 => "not-paired",
                    2 => "incompatible",
                    other => return Err(format!("closed after a message of type {other}")),
                };
                same(state.field("erro").field("camada").str(), "mensagem")?;
                same(state.field("erro").field("codigo").str(), code)
            } else {
                same(state.field("erro"), &Json::Null)
            }
        }

        // ---- the same conversations, with the real state machines ---------

        /// The payload of a client `data` frame.
        fn client_payload(frame: &[u8]) -> Result<Vec<u8>, String> {
            match porecatu_protocol::envelope::decode_client(Bytes::copy_from_slice(frame))
                .map_err(|e| e.to_string())?
            {
                ClientEnvelope::Data { payload } => Ok(payload.as_bytes().to_vec()),
                other => Err(format!("a client frame that is not `data`: {other:?}")),
            }
        }

        fn host_events_sends(events: &[porecatu_protocol::session::HostEvent]) -> Vec<Vec<u8>> {
            events
                .iter()
                .filter_map(|event| match event {
                    porecatu_protocol::session::HostEvent::Send(payload) => Some(payload.to_vec()),
                    _ => None,
                })
                .collect()
        }

        /// Replays a conversation with a [`ClientSession`] and a
        /// [`HostChannel`] (the fixed ephemeral keys go in through the
        /// `test-vectors` constructors) instead of the handshake and record
        /// layers one by one: what each writes must match the vector byte for
        /// byte, and what the other reports must be the message of the step.
        /// The answers the host owes follow the same rules as [`session`].
        ///
        /// The client reads `msg2` of `XX` at the instant of its `msg3`, as
        /// the vectors' clock says; the host reads `msg1` at the instant of
        /// its `msg2`.
        pub fn session_machines(v: &Json) -> Result<(), String> {
            use porecatu_protocol::host_id::HostId;
            use porecatu_protocol::message::PairRequest;
            use porecatu_protocol::pairing_uri::PairingUri;
            use porecatu_protocol::session::{ClientEvent, ClientSession, HostChannel, HostEvent};

            let keys = keys_of(v);
            let id = HostId::parse(v.field("host_id").str()).map_err(|e| format!("{e:?}"))?;
            let channel = uint(v.field("canal"));
            let host_version = {
                let version = array(v.field("versao"));
                [uint(&version[0]), uint(&version[1])]
            };
            let kind = match v.field("handshake").str() {
                "XX" => HandshakeKind::Pair,
                "IK" => HandshakeKind::Connect,
                other => return Err(format!("unknown handshake {other}")),
            };
            let client_pair = StaticKeypair::from_private(keys.client_static);
            let host_pair = StaticKeypair::from_private(keys.host_static);
            let token_host: Option<[u8; 16]> = (!v.field("token_host").is_null()).then(|| {
                bytes_of(&typed(v.field("token_host")))
                    .try_into()
                    .expect("16 bytes")
            });
            let paired: Vec<[u8; 32]> = array(v.field("pareados"))
                .iter()
                .map(|k| bytes32(&typed(k)))
                .collect();
            let steps: Vec<Step> = array(v.field("passos")).iter().map(step_of).collect();
            let handshake_len = if kind == HandshakeKind::Pair { 3 } else { 2 };
            if steps.len() <= handshake_len {
                return Err("shorter than its handshake".to_owned());
            }
            let frames_of =
                |frames: &[Bytes]| -> Vec<Vec<u8>> { frames.iter().map(|f| f.to_vec()).collect() };

            // Step 0: the client writes msg1, inside a handshake-start.
            let first = &steps[0];
            if !first.from_client || first.item.is_some() {
                return Err("step 0 is the client's msg1".to_owned());
            }
            let (mut client, frames) = match kind {
                HandshakeKind::Pair => {
                    // The pair-request is the payload of msg3: the invitation
                    // gets its token.
                    let item = steps[2]
                        .item
                        .as_ref()
                        .ok_or("step 2 carries the pair-request")?;
                    let request =
                        PairRequest::decode(&cbor::encode(item)).map_err(|e| e.to_string())?;
                    let invite = PairingUri {
                        major: host_version[0],
                        relay: "wss://relay.example.org".to_owned(),
                        host_id: id.clone(),
                        host_key: host_pair.public(),
                        token: request.token,
                        name: "Workstation".to_owned(),
                    };
                    ClientSession::pair_with_ephemeral(
                        &invite,
                        &client_pair,
                        &request.device,
                        request.platform,
                        first.now,
                        &keys.client_ephemeral,
                    )
                }
                HandshakeKind::Connect => ClientSession::connect_with_ephemeral(
                    &id,
                    &host_pair.public(),
                    &client_pair,
                    first.now,
                    &keys.client_ephemeral,
                ),
            }
            .map_err(|e| e.to_string())?;
            same(&frames_of(&frames), &first.frames).map_err(|e| format!("frame 0: {e}"))?;
            let start_payload = client_payload(&frames[0])?;
            let start = porecatu_protocol::envelope::decode_handshake_start(Bytes::from(
                start_payload.clone(),
            ))
            .map_err(|e| e.to_string())?;
            same(&vec![start.msg1.to_vec()], &first.records).map_err(|e| format!("msg1: {e}"))?;

            let mut host =
                HostChannel::with_ephemeral(&host_pair, &id, first.now, keys.host_ephemeral);
            let second = &steps[1];
            let events = host
                .receive(&start_payload, second.now)
                .map_err(|e| e.to_string())?;

            // Step 1: the host answers with msg2.
            if second.from_client || second.item.is_some() {
                return Err("step 1 is the host's msg2".to_owned());
            }
            let msg2 = host_events_sends(&events);
            same(&msg2, &second.records).map_err(|e| format!("msg2: {e}"))?;
            let msg2_frames: Vec<Vec<u8>> = msg2
                .iter()
                .map(|p| frame_of_host(channel, p.clone()))
                .collect();
            same(&msg2_frames, &second.frames).map_err(|e| format!("frame 1: {e}"))?;
            let [msg2] = msg2.as_slice() else {
                return Err("msg2 is one payload".to_owned());
            };
            let msg2_data = Bytes::from(frame_of_client(msg2.clone()));

            let mut owed = None;
            match kind {
                HandshakeKind::Connect => {
                    let connecting = events.iter().find_map(|event| match event {
                        HostEvent::DeviceConnecting { device_key } => Some(*device_key),
                        _ => None,
                    });
                    same(&connecting, &Some(client_pair.public()))?;
                    if !paired.contains(&client_pair.public()) {
                        owed = Some(Decision::NotPaired);
                    }
                    let read = client
                        .receive(msg2_data, second.now)
                        .map_err(|e| e.to_string())?;
                    same(&read, &vec![ClientEvent::HandshakeComplete])?;
                }
                HandshakeKind::Pair => {
                    let third = &steps[2];
                    let read = client
                        .receive(msg2_data, third.now)
                        .map_err(|e| e.to_string())?;
                    let [ClientEvent::Send(frame), ClientEvent::HandshakeComplete] =
                        read.as_slice()
                    else {
                        return Err(format!("the client answers msg2 with msg3: {read:?}"));
                    };
                    same(&vec![frame.to_vec()], &third.frames)
                        .map_err(|e| format!("frame 2: {e}"))?;
                    let msg3 = client_payload(frame)?;
                    same(&vec![msg3.clone()], &third.records).map_err(|e| format!("msg3: {e}"))?;
                    let item = third
                        .item
                        .as_ref()
                        .ok_or("step 2 carries the pair-request")?;
                    let expected =
                        PairRequest::decode(&cbor::encode(item)).map_err(|e| e.to_string())?;
                    let reading = host.receive(&msg3, third.now).map_err(|e| e.to_string())?;
                    let [
                        HostEvent::PairRequested {
                            device_key,
                            request,
                        },
                    ] = reading.as_slice()
                    else {
                        return Err(format!("the host reads the pair-request: {reading:?}"));
                    };
                    same(device_key, &client_pair.public())?;
                    same(request, &expected)?;
                    // The host's decision about the token.
                    let token_ok = token_host.is_some_and(|held| {
                        PairingToken::new(held, 0).matches_and_consume(&request.token, third.now)
                    });
                    owed = Some(Decision::Pairing { token_ok });
                }
            }

            // The steps after the handshake.
            let mut decision = owed;
            let mut closed = false;
            let mut last_host_item: Option<Value> = None;
            for (offset, step) in steps[handshake_len..].iter().enumerate() {
                let at = |e: String| format!("step {}: {e}", handshake_len + offset);
                if closed {
                    return Err(at("a step after the close".to_owned()));
                }
                if step.records.is_empty() {
                    // The host closes the channel.
                    let [frame] = step.frames.as_slice() else {
                        return Err(at("a close is one frame".to_owned()));
                    };
                    let envelope = porecatu_protocol::envelope::decode_host(frame.clone().into())
                        .map_err(|e| at(e.to_string()))?;
                    same(
                        &envelope,
                        &HostEnvelope::CloseChannel {
                            channel: ChannelId(channel),
                            reason: CloseReason::Normal,
                        },
                    )
                    .map_err(at)?;
                    same(&step.from_client, &false).map_err(at)?;
                    closed = true;
                    continue;
                }
                let item = step
                    .item
                    .as_ref()
                    .ok_or_else(|| at("a message step needs `mensagem`".to_owned()))?;
                let wire = cbor::encode(item);
                let direction = if step.from_client {
                    Direction::ClientToHost
                } else {
                    Direction::HostToClient
                };
                let message =
                    message::decode(&wire, direction).map_err(|e| at(format!("{e:?}")))?;
                same(&message::encode(&message), &wire).map_err(at)?;

                if step.from_client {
                    let frames = client
                        .send(&message, step.now)
                        .map_err(|e| at(e.to_string()))?;
                    same(&frames_of(&frames), &step.frames)
                        .map_err(|e| at(format!("frames: {e}")))?;
                    let records = frames
                        .iter()
                        .map(|f| client_payload(f))
                        .collect::<Result<Vec<_>, _>>()?;
                    same(&records, &step.records).map_err(|e| at(format!("records: {e}")))?;
                    let mut events = Vec::new();
                    for record in &records {
                        events.extend(
                            host.receive(record, step.now)
                                .map_err(|e| at(e.to_string()))?,
                        );
                    }
                    same(&events, &vec![HostEvent::Message(message.clone())])
                        .map_err(|e| at(format!("host events: {e}")))?;
                    if type_of(item) == 0 {
                        decision = Some(Decision::Hello {
                            same_version: version_of(item).map_err(at)? == host_version,
                        });
                    }
                } else {
                    let payloads =
                        if matches!(decision, Some(Decision::NotPaired)) && type_of(item) == 70 {
                            host.reject_not_paired(step.now)
                        } else {
                            host.send(&message, step.now)
                        }
                        .map_err(|e| at(e.to_string()))?;
                    let payloads: Vec<Vec<u8>> = payloads.iter().map(|p| p.to_vec()).collect();
                    same(&payloads, &step.records).map_err(|e| at(format!("records: {e}")))?;
                    let frames: Vec<Vec<u8>> = payloads
                        .iter()
                        .map(|p| frame_of_host(channel, p.clone()))
                        .collect();
                    same(&frames, &step.frames).map_err(|e| at(format!("frames: {e}")))?;
                    let mut events = Vec::new();
                    for payload in &payloads {
                        events.extend(
                            client
                                .receive(Bytes::from(frame_of_client(payload.clone())), step.now)
                                .map_err(|e| at(e.to_string()))?,
                        );
                    }
                    same(&events, &vec![ClientEvent::Message(message.clone())])
                        .map_err(|e| at(format!("client events: {e}")))?;
                    if let Some(owed) = decision.take() {
                        owed.check(item, host_version).map_err(at)?;
                    }
                    last_host_item = Some(item.clone());
                }
            }

            // The final state follows from the host's last message.
            let state = v.field("resultado");
            let result = state.field("estado").str();
            same(&closed, &(result == "fechada"))?;
            if closed {
                let last = last_host_item.ok_or("closed without a host message")?;
                let code = match type_of(&last) {
                    61 => "token-invalid",
                    70 => "not-paired",
                    2 => "incompatible",
                    other => return Err(format!("closed after a message of type {other}")),
                };
                same(state.field("erro").field("camada").str(), "mensagem")?;
                same(state.field("erro").field("codigo").str(), code)
            } else {
                same(state.field("erro"), &Json::Null)
            }
        }
    }

    #[cfg(not(all(feature = "message", feature = "test-vectors")))]
    mod fixed {
        use super::*;

        pub fn noise(_: &Json) -> Result<(), String> {
            Ok(())
        }

        pub fn records(_: &Json) -> Result<(), String> {
            Ok(())
        }

        pub fn session(_: &Json) -> Result<(), String> {
            Ok(())
        }

        pub fn session_machines(_: &Json) -> Result<(), String> {
            Ok(())
        }
    }

    fn is_cacophony(path: &str) -> bool {
        path.rsplit('/')
            .next()
            .is_some_and(|name| name.starts_with("cacophony-"))
    }

    #[test]
    fn noise_vectors() {
        let count = run_all("noise", |path, v| {
            if is_cacophony(path) {
                check_cacophony(v)
            } else {
                fixed::noise(v)
            }
        });
        assert!(count >= 6, "only {count} noise files");
        // The cacophony file and the two handshakes, plus the three refusals.
        let files: Vec<String> = load("noise").into_iter().map(|(path, _)| path).collect();
        for wanted in [
            "noise/cacophony-xx-ik.json",
            "noise/xx-porecatu.json",
            "noise/ik-porecatu.json",
            "noise/xx-chave-do-qr-diferente.json",
            "noise/xx-dh-nulo-no-host.json",
            "noise/ik-dh-nulo-no-cliente.json",
        ] {
            assert!(files.iter().any(|f| f == wanted), "missing {wanted}");
        }
    }

    #[test]
    fn record_vectors() {
        let count = run_all("registros", |_, v| fixed::records(v));
        assert!(count >= 11, "only {count} record vectors");
    }

    #[test]
    fn session_vectors() {
        let count = run_all("sessoes", |_, v| fixed::session(v));
        assert!(count >= 6, "only {count} session vectors");
    }

    /// The same conversations, with `ClientSession` and `HostChannel`.
    #[test]
    fn session_vectors_with_the_state_machines() {
        let count = run_all("sessoes", |_, v| fixed::session_machines(v));
        assert!(count >= 6, "only {count} session vectors");
    }

    /// The transcripts the TypeScript implementation wrote (`sessoes-ts/`,
    /// see `ts/test/transcripts.test.ts`): the crate reproduces them byte for
    /// byte, at the level of the handshake and record layers and with the
    /// state machines. This is the TS-to-Rust half of the cross test.
    #[test]
    fn typescript_transcripts() {
        let count = run_all("sessoes-ts", |_, v| {
            fixed::session(v)?;
            fixed::session_machines(v)
        });
        assert!(count >= 3, "only {count} TypeScript transcripts");
        let files: Vec<String> = load("sessoes-ts")
            .into_iter()
            .map(|(path, _)| path)
            .collect();
        for wanted in [
            "sessoes-ts/pareamento-aceito.json",
            "sessoes-ts/conexao-ik-pareado.json",
            "sessoes-ts/conexao-ik-desconhecido.json",
        ] {
            assert!(files.iter().any(|f| f == wanted), "missing {wanted}");
        }
    }
}
